from concurrent.futures import ThreadPoolExecutor

def job(k):
    if k == 3:
        raise ValueError(f"bad input {k}")
    return k * k

with ThreadPoolExecutor(max_workers=3) as ex:
    futures = {k: ex.submit(job, k) for k in range(6)}
    outcomes = {}
    for k, f in futures.items():
        try:
            outcomes[k] = ("ok", f.result())
        except ValueError as e:
            outcomes[k] = ("error", str(e))

for k in sorted(outcomes):
    print(k, outcomes[k])
print("every task accounted for:", len(outcomes) == 6)

from multiprocessing import Pool

if __name__ == "__main__":
    with Pool(2) as pool:
        try:
            print(pool.map(lambda k: k * k, range(4)))
        except Exception as e:
            print("error type:", type(e).__name__)
            print("the lambda could not be sent to the worker at all")

from multiprocessing import Process, Value

def bump(shared, n):
    for _ in range(n):
        with shared.get_lock():
            shared.value += 1

if __name__ == "__main__":
    counter = Value("i", 0)
    procs = [Process(target=bump, args=(counter, 2500)) for _ in range(4)]
    for p in procs:
        p.start()
    for p in procs:
        p.join()
    print("expected:", 4 * 2500)
    print("shared counter:", counter.value)
    print("exact:", counter.value == 4 * 2500)

import threading

held = 0
lock = threading.Lock()
failures = []

def acquire():
    global held
    with lock:
        held += 1

def release():
    global held
    with lock:
        held -= 1

def task(k):
    acquire()
    try:
        if k == 2:
            raise RuntimeError("disk full")
        return k
    finally:
        release()                    # runs on success AND on failure

def run(k):
    try:
        task(k)
    except RuntimeError as e:
        failures.append(str(e))

threads = [threading.Thread(target=run, args=(k,)) for k in range(4)]
for t in threads:
    t.start()
for t in threads:
    t.join()

print("failures recorded:", failures)
print("resources still held after a mid-task failure:", held)

import threading

accounts = {"a": 500, "b": 500}
locks = {name: threading.Lock() for name in accounts}

def transfer(src, dst, amount):
    first, second = sorted((src, dst))       # one global lock order, agreed by everyone
    with locks[first]:
        with locks[second]:
            accounts[src] -= amount
            accounts[dst] += amount

threads = []
for k in range(20):
    src, dst = ("a", "b") if k % 2 == 0 else ("b", "a")
    threads.append(threading.Thread(target=transfer, args=(src, dst, 10)))
for t in threads:
    t.start()
for t in threads:
    t.join()

print("balances after 20 opposing transfers:", accounts)
print("invariant 1 - total conserved (500 + 500):", accounts["a"] + accounts["b"] == 1000)
print("invariant 2 - equal opposing flows cancel out:", accounts == {"a": 500, "b": 500})

